import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"6.4 低压线路的敷设与连接","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-4-di-ya-xian-lu-de-fu-she-yu-lian-jie.md","filePath":"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-4-di-ya-xian-lu-de-fu-she-yu-lian-jie.md","lastUpdated":1793095197000}'),o={name:"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-4-di-ya-xian-lu-de-fu-she-yu-lian-jie.md"};function e(n,t,s,d,h,g){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_6-4-低压线路的敷设与连接" tabindex="-1">6.4 低压线路的敷设与连接 <a class="header-anchor" href="#_6-4-低压线路的敷设与连接" aria-label="Permalink to &quot;6.4 低压线路的敷设与连接&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>线选好了,还得&quot;敷得好、接得牢&quot;。这一节讲低压线路的<strong>敷设方式</strong>(明敷/暗敷)、<strong>导线颜色</strong>的识别,以及最关键的手艺——<strong>导线连接</strong>(接头要牢、要绝缘好)。接头工艺不好是线路故障和火灾的重要源头。</p><h2 id="一、敷设方式" tabindex="-1">一、敷设方式 <a class="header-anchor" href="#一、敷设方式" aria-label="Permalink to &quot;一、敷设方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>特点</th><th>适用场合</th></tr></thead><tbody><tr><td><strong>明敷</strong></td><td>导线沿墙壁、天花板、支架<strong>明露</strong>敷设</td><td>便于检修,工业厂房多用</td></tr><tr><td><strong>暗敷</strong></td><td>导线穿管<strong>预埋在墙内、地下</strong></td><td>美观、安全,民用建筑多用</td></tr><tr><td>穿管敷设</td><td>导线穿在钢管/塑料管内</td><td>保护导线,防潮防机械损伤</td></tr></tbody></table><p><strong>穿管敷设注意</strong>:</p><ul><li>管内导线总截面一般不超过管内截面的 <strong>40%</strong>,便于穿线和散热;</li><li>不同回路的导线(照明/动力/信号)原则上分开穿管;</li><li>穿管时防止导线绝缘层被划伤。</li></ul><h2 id="二、导线颜色的识别-必背" tabindex="-1">二、导线颜色的识别(必背) <a class="header-anchor" href="#二、导线颜色的识别-必背" aria-label="Permalink to &quot;二、导线颜色的识别(必背)&quot;">​</a></h2><p>低压线路中,导线颜色有规定,一眼识别:</p><table tabindex="0"><thead><tr><th>导线</th><th>颜色</th></tr></thead><tbody><tr><td>相线(火线)</td><td><strong>红、黄、绿</strong>(三相各一色)</td></tr><tr><td>中性线(零线)</td><td><strong>蓝色(浅蓝)</strong></td></tr><tr><td>保护接地线(PE)</td><td><strong>黄绿双色</strong></td></tr></tbody></table><blockquote><p>💡 判断口诀:<strong>&quot;相线红黄绿、零线蓝、地线黄绿花&quot;</strong>。看到黄绿双色线就是接地线,别当普通线用。</p></blockquote><h2 id="三、导线连接的基本要求" tabindex="-1">三、导线连接的基本要求 <a class="header-anchor" href="#三、导线连接的基本要求" aria-label="Permalink to &quot;三、导线连接的基本要求&quot;">​</a></h2><p>导线连接处是线路最薄弱的环节,必须满足:</p><ol><li><strong>电阻小</strong>:连接处电阻不得大于导线本身的电阻,否则发热;</li><li><strong>机械强度足够</strong>:接头要牢固,不脱线;</li><li><strong>绝缘恢复良好</strong>:接头处要包好绝缘胶带,恢复绝缘;</li><li><strong>耐腐蚀、耐振动</strong>:长期使用不氧化、不松动。</li></ol><blockquote><p>⚠️ 连接处电阻过大 → 局部发热 → 绝缘老化 → 火灾隐患。这是电气火灾最常见原因之一(呼应第 12 章)。</p></blockquote><h2 id="四、常见连接工艺" tabindex="-1">四、常见连接工艺 <a class="header-anchor" href="#四、常见连接工艺" aria-label="Permalink to &quot;四、常见连接工艺&quot;">​</a></h2><ul><li><strong>绞接(缠绕)</strong>:两股导线拧在一起,用于小截面导线;</li><li><strong>压接</strong>:用压线钳和管形线鼻子(接线端子)压接,用于较粗导线和端子连接;</li><li><strong>焊接</strong>:锡焊等,用于特殊场合;</li><li>接头完成后<strong>缠绝缘胶带</strong>(相线接头)恢复绝缘;</li><li>接在端子排(螺丝)上时,导线要拧紧、不露线头。</li></ul><h2 id="五、操作要点" tabindex="-1">五、操作要点 <a class="header-anchor" href="#五、操作要点" aria-label="Permalink to &quot;五、操作要点&quot;">​</a></h2><ul><li>导线接入端子前,<strong>剥绝缘层长度适当</strong>,不伤芯线;</li><li>多股导线接入端子前<strong>先拧紧(或加线鼻子)</strong>,防止毛刺短路;</li><li>接线完毕<strong>逐一检查</strong>是否有线头外露、是否有虚接;</li><li>电气设备金属外壳接线端子接<strong>保护接地线(黄绿双色)</strong>。</li></ul><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 相线红黄绿、零线蓝、保护地线黄绿双色。</li><li>✅ 接头要求:电阻小、强度够、绝缘恢复好。</li><li>✅ 管内导线总截面不超过管内的 40%。</li><li>⚠️ 易混点:零线(蓝)和地线(黄绿双色)颜色不同,用途不同,别接错。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>明敷/暗敷/穿管,穿管要留余量(≤40%)。</li><li>导线颜色识别:火线红黄绿、零线蓝、地线黄绿双色。</li><li>接头工艺决定线路安全:电阻小、牢固、绝缘恢复。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)低压线路中,相线(火线)一般使用红、黄、绿三种颜色。( )</li><li>(单选)中性线(零线)的标识颜色是()。 A. 蓝色　B. 黄绿双色　C. 红色　D. 黑色</li><li>(判断)导线连接处电阻过大,会导致局部发热,是电气火灾的隐患。( )</li><li>(判断)穿管敷设时,管内导线总截面不得超过管内径截面的 40%。( )</li><li>(单选)保护接地线(PE)的颜色是()。 A. 蓝　B. 黄绿双色　C. 红　D. 白</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。相线用红、黄、绿三色区分三相。</li><li><strong>A</strong>。零线为蓝色(浅蓝)。</li><li><strong>√</strong>。接头电阻过大发热,是火灾隐患。</li><li><strong>√</strong>。管内导线总截面 ≤ 管内截面的 40%。</li><li><strong>B</strong>。保护接地线为黄绿双色。</li></ol></details>',26)])])}const b=a(o,[["render",e]]);export{c as __pageData,b as default};
